-- DocHUB seed: in the Excel-A4 PDF layout of F3QCPF06 (original and copies) the เวลา column prints only the time (HH:mm) when it is a
-- date-time column. Generated by server/scripts/mdPdfTemplate.cjs --time-only — do not edit by hand. Only touches that one column entry.
SET NOCOUNT ON;
UPDATE Files
SET pdf_templates = REPLACE(pdf_templates, N'"columnName":"เวลา","header":"เวลา","widthMm":9.5,"align":"center"}', N'"columnName":"เวลา","header":"เวลา","widthMm":9.5,"align":"center","timeOnly":true}'),
    updated_at = SYSUTCDATETIME()
WHERE is_deleted = 0 AND pdf_templates LIKE N'%f3qcpf06-excel-a4-portrait%'
  AND pdf_templates LIKE N'%"columnName":"เวลา","header":"เวลา","widthMm":9.5,"align":"center"}%';
SELECT N'inserted' AS result;
